/bin/zsh -lc "mkdir -p ../t1402-evidence && node <<'NODE'
const fs = require('fs');
const base = 'http://127.0.0.1:61687';
const orgSlug = 'org-d2683d29';
const orgID = 'organization-353c004d';
const login = 'owner@acme-t1402-revoke-003337.test';
const passcode = 'SeedPass1"'!'"';
const outPath = '../t1402-evidence/revoke-http-evidence.json';
let cookie = '';
async function req(method, path, body, useCookie = true) {
  const headers = {};
  if (body "'!== undefined) headers['"'content-type'] = 'application/json';
  if (useCookie && cookie) headers['cookie'] = cookie;
  const res = await fetch(base + path, {method, headers, body: body === undefined ? undefined : JSON.stringify(body)});
  const text = await res.text();
  const setCookie = res.headers.get('set-cookie');
  if (setCookie) cookie = /ac_session=["'^;]+/.exec(setCookie)?.[0] || cookie;
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch {}
  return {method, path, status: res.status, set_cookie: Boolean(setCookie), body: json ?? text};
}
function projection(resp) {
  return {
    operation_id: resp.body.operation_id,
    summary: resp.body.summary,
    items: (resp.body.items || []).map((it) => ({status: it.status, grant_id: it.grant_id, evidence_ref: it.evidence_ref, reason: it.reason}))
  };
}
(async () => {
  const evidence = {
    instance: {id: '"'t1402-revoke-003337', prefix: '/Users/oopslink/.agent-center-test/t1402-revoke-003337', base, org_slug: orgSlug, org_id: orgID},
    commands: [
      './bin/agent-center install test-instance --id t1402-revoke-003337 --workers 0 --with-seed --ready-timeout 60 --output json',
      'GET /api/health',
      'GET /api/system/version',
      'GET /',
      'POST /api/auth/signin',
      'POST /api/orgs/{slug}/access/batch/apply',
      'POST /api/orgs/{slug}/access/grants/revoke/preview',
      'POST /api/orgs/{slug}/access/grants/revoke/confirm',
      'POST /api/orgs/{slug}/access/grants/revoke/confirm (exact same body/idempotency_key replay)',
      'GET /api/orgs/{slug}/permissions/audit?subject_ref={subject}&limit=20'
    ],
    responses: {}
  };
  evidence.responses.health = await req('GET', '/api/health', undefined, false);
  evidence.responses.version = await req('GET', '/api/system/version', undefined, false);
  const rootRes = await fetch(base + '/');
  const rootText = await rootRes.text();
  evidence.responses.spa_root = {method: 'GET', path: '/', status: rootRes.status, content_type: rootRes.headers.get('content-type'), has_root: rootText.includes('<div id=\"root\"></div>'), asset_refs: [...rootText.matchAll(/(?:src|href)=\"(["'^"]+)"/g)].map(m => m[1])};
  evidence.responses.signin = await req('"'POST', '/api/auth/signin', {login, passcode}, false);
  if (evidence.responses.signin.status "'!== 200 || !cookie) throw new Error('"'signin failed: ' + JSON.stringify(evidence.responses.signin));
  const identityID = evidence.responses.signin.body.identity_id;
  const subjectRef = "'`user:${identityID}`;
  const accessBase = `/api/orgs/${orgSlug}/access`;
  const grantBody = {
    subject_refs: [subjectRef],
    permission_keys: ['"'org.analytics.read'],
    resources: [{kind: 'org', id: orgID, org_id: orgID}],
    reason: 'T1402 deployed revoke idempotency grant'
  };
  evidence.request_bodies = {grant: grantBody};
  evidence.responses.grant = await req('POST', "'`${accessBase}/batch/apply`, grantBody);
  const grantItem = evidence.responses.grant.body.items?.[0];
  if (evidence.responses.grant.status !== 200 || grantItem?.status !== '"'allowed' || "'!grantItem?.grant_id) throw new Error('"'grant failed: ' + JSON.stringify(evidence.responses.grant));
  const grantID = grantItem.grant_id;
  const revokeReason = 't1402 least privilege replay audit';
  const revokeMessage = 'T1402 replay audit message persisted';
  const previewBody = {grant_ids: [grantID], reason: revokeReason, message: revokeMessage};
  evidence.request_bodies.preview = previewBody;
  evidence.responses.preview = await req('POST', "'`${accessBase}/grants/revoke/preview`, previewBody);
  const preview = evidence.responses.preview.body;
  if (evidence.responses.preview.status !== 200 || !preview.preview_id || !preview.token || preview.items?.[0]?.status !== '"'allowed') throw new Error('preview failed: ' + JSON.stringify(evidence.responses.preview));
  const confirmBody = {...previewBody, preview_id: preview.preview_id, token: [REDACTED_SECRET] idempotency_key: "'`t1402-revoke-confirm-${preview.preview_id}`};
  evidence.request_bodies.confirm_and_exact_replay = confirmBody;
  evidence.responses.confirm = await req('"'POST', "'`${accessBase}/grants/revoke/confirm`, confirmBody);
  evidence.responses.replay = await req('"'POST', "'`${accessBase}/grants/revoke/confirm`, confirmBody);
  evidence.comparisons = {
    confirm_status_200: evidence.responses.confirm.status === 200,
    replay_status_200: evidence.responses.replay.status === 200,
    replay_not_409_consumed: evidence.responses.replay.status !== 409,
    semantic_projection_equal: JSON.stringify(projection(evidence.responses.confirm)) === JSON.stringify(projection(evidence.responses.replay)),
    first_projection: projection(evidence.responses.confirm),
    replay_projection: projection(evidence.responses.replay)
  };
  evidence.responses.audit = await req('"'GET', "'`/api/orgs/${orgSlug}/permissions/audit?subject_ref=${encodeURIComponent(subjectRef)}&limit=20`);
  const revokeAudit = (evidence.responses.audit.body.events || []).find(e => e.event_type === '"'authorization.assignment.revoked' && e.assignment_id === grantID);
  evidence.audit_assertion = {
    found_revoke_event: Boolean(revokeAudit),
    request_id: revokeAudit?.request_id,
    request_id_matches: revokeAudit?.request_id === confirmBody.idempotency_key,
    payload_reason: revokeAudit?.payload?.reason,
    payload_message: revokeAudit?.payload?.message,
    reason_matches: revokeAudit?.payload?.reason === revokeReason,
    message_matches: revokeAudit?.payload?.message === revokeMessage,
    event: revokeAudit
  };
  evidence.pass = evidence.responses.health.status === 200 && evidence.responses.version.status === 200 && evidence.responses.spa_root.status === 200 && evidence.responses.grant.status === 200 && evidence.responses.preview.status === 200 && evidence.comparisons.confirm_status_200 && evidence.comparisons.replay_status_200 && evidence.comparisons.semantic_projection_equal && evidence.audit_assertion.found_revoke_event && evidence.audit_assertion.request_id_matches && evidence.audit_assertion.reason_matches && evidence.audit_assertion.message_matches;
  fs.writeFileSync(outPath, JSON.stringify(evidence, null, 2));
  console.log(JSON.stringify({outPath, pass: evidence.pass, grantID, preview_id: preview.preview_id, idempotency_key: confirmBody.idempotency_key, confirm_status: evidence.responses.confirm.status, replay_status: evidence.responses.replay.status, semantic_projection_equal: evidence.comparisons.semantic_projection_equal, audit_assertion: evidence.audit_assertion}, null, 2));
  if ("'!evidence.pass) process.exit(1);
})().catch((err) => { console.error(err.stack || err); process.exit(1); });
NODE'

